// evaluation context.
enum RatifyStatus ratify_verifier_context_hash(const struct RatifyVerifierContext *ctx,
                                               unsigned char *out_32,
                                               char **err_out);

// Return the canonical revocation-list signing bytes as a lowercase hex string.
char *ratify_revocation_list_sign_bytes_hex(const char *list_json, char **err_out);

// Return the canonical revocation-push signing bytes as a lowercase hex string.
char *ratify_revocation_push_sign_bytes_hex(const char *push_json, char **err_out);

// Return the Ed25519 component of a RevocationPush signature as hex. Free with `ratify_string_free`.
char *ratify_revocation_push_sig_ed25519_hex(const char *push_json,
                                             char **err_out);

// Return the ML-DSA-65 component of a RevocationPush signature as hex. Free with `ratify_string_free`.
char *ratify_revocation_push_sig_ml_dsa_65_hex(const char *push_json,
                                               char **err_out);

// Return the canonical key-rotation signing bytes as a lowercase hex string.
char *ratify_key_rotation_sign_bytes_hex(const char *rotation_json, char **err_out);

// Return the canonical session-token signing bytes as a lowercase hex string.
char *ratify_session_token_sign_bytes_hex(const char *token_json, char **err_out);

// Return the session-token MAC bytes as a lowercase hex string. Free with `ratify_string_free`.
char *ratify_session_token_mac_hex(const char *token_json, char **err_out);

// Return the canonical transaction-receipt signing bytes as a lowercase hex string.
char *ratify_transaction_receipt_sign_bytes_hex(const char *receipt_json, char **err_out);

// Return the canonical witness-entry signing bytes as a lowercase hex string.
char *ratify_witness_entry_sign_bytes_hex(const char *entry_json, char **err_out);

// Return the Ed25519 component of a WitnessEntry signature as hex. Free with `ratify_string_free`.
char *ratify_witness_entry_sig_ed25519_hex(const char *entry_json, char **err_out);

// Return the ML-DSA-65 component of a WitnessEntry signature as hex. Free with `ratify_string_free`.
char *ratify_witness_entry_sig_ml_dsa_65_hex(const char *entry_json,
                                             char **err_out);

// Verify a single streamed turn against an already-issued session token.
//
// DEPRECATED: presentation checks only — this form cannot enforce a
// required scope, single-use challenges, or verifier-side session/stream
// checks, so a token holder passes it for any protected action. Use
// `ratify_verify_streamed_turn_opts`. Retained for compatibility through
// the v1.0.0-* releases.
//
// This is the fast path for embedded streaming: after a full `verify_bundle`
// that issued a session token, each subsequent turn is verified with this
// function — no cert chain re-verification needed.
//
// Returns a `RatifyVerifyResult*` (same type as `ratify_verify_bundle`).
// Free with `ratify_verify_result_free`.
//
// - `token_json`          — JSON of the `SessionToken` returned by `ratify_session_token_issue`.
// - `session_secret`      — the HMAC secret used when the token was issued (raw bytes, ≥1 byte).
// - `challenge` / `challenge_len` — the fresh challenge bytes for this turn.
// - `challenge_at`        — Unix timestamp the challenge was issued.
// - `challenge_sig_json`  — `HybridSignature` JSON produced by the agent.
// - `session_context`     — optional 32-byte session context (NULL + 0 = none).
// - `stream_id`           — optional 32-byte stream ID (NULL + 0 = none).
// - `stream_seq`          — highest sequence number already accepted (0 = first turn).
// - `now_unix`            — current clock; 0 = use system clock.
struct RatifyVerifyResult *ratify_verify_streamed_turn(const char *token_json,
                                                       const unsigned char *session_secret,
                                                       uintptr_t session_secret_len,
                                                       const unsigned char *challenge,
                                                       uintptr_t challenge_len,
                                                       int64_t challenge_at,
                                                       const char *challenge_sig_json,
                                                       const unsigned char *session_context,
                                                       uintptr_t session_context_len,
                                                       const unsigned char *stream_id,
                                                       uintptr_t stream_id_len,
                                                       int64_t stream_seq,
                                                       int64_t now_unix,
                                                       char **err_out);

// Options-object streamed-turn verification (SPEC §5.13).
//
// Verifies one turn against a previously issued SessionToken and enforces
// the verifier-side controls the positional `ratify_verify_streamed_turn`
// cannot: `opts->required_scope` is checked against the token's cached
// effective scope (`scope_denied` on miss), `opts->session_context` /
// `opts->stream` are the verifier-side expectations checked against the
// presented bindings with the same statuses as full verification, and a
// non-NULL `store` makes the per-turn challenge single-use (consulted,
// without consuming, after the session token's HMAC authenticates the
// presentation and before the per-turn hybrid challenge signature is
// verified; atomically consumed after that signature verifies — before
// the scope check; store failures normalize to the canonical
// unknown_challenge result).
//
// `opts` is `RatifyStreamedVerifyOptions` — deliberately not the full
// `RatifyVerifyOptions`, so revocation callbacks and constraint context
// can never be passed and silently ignored. Callers who need fresh
// revocation or policy semantics run full bundle verification instead.
//
// - `session_context` / `stream_id` / `stream_seq` — the PRESENTED
//   bindings the agent signed (NULL + 0 = unbound), distinct from the
//   expectations in `opts`.
// - `opts` may be NULL for default options; `now` comes from
//   `opts->now_unix` (0 = system clock).
// - `store` may be NULL to skip single-use enforcement.
// - `opts->stream` is a caller-owned snapshot — see its declaration for
//   the atomic-advance requirement.
enum RatifyStatus ratify_verify_streamed_turn_opts(const char *token_json,
                                                   const unsigned char *session_secret,
                                                   uintptr_t session_secret_len,
                                                   const unsigned char *challenge,
                                                   uintptr_t challenge_len,
                                                   int64_t challenge_at,
                                                   const char *challenge_sig_json,
                                                   const unsigned char *session_context,
                                                   uintptr_t session_context_len,
                                                   const unsigned char *stream_id,
                                                   uintptr_t stream_id_len,
                                                   int64_t stream_seq,
                                                   const struct RatifyStreamedVerifyOptions *opts,
                                                   const struct RatifyChallengeStore *store,
                                                   struct RatifyVerifyResult **out,
                                                   char **err_out);

// Full transaction-receipt verification with explicit valid/error_reason outputs.
//
// Writes 1 to `*valid_out` on success, 0 on failure.
// On failure, `*err_out` contains the error_reason string (free with `ratify_error_free`).
// Returns `RatifyOk` on parse success (the receipt may still be invalid — check `*valid_out`).
enum RatifyStatus ratify_transaction_receipt_verify_full(const char *receipt_json,
                                                         int64_t now_unix,
                                                         int *valid_out,
                                                         char **err_out);

// Compute the 32-byte request_hash over the SPEC §6.4.9 operation
// context: the specific action a presentation authorizes. Every string
// may be NULL (= empty); `payload_digest` is NULL + 0 (= none) or
// exactly 32 bytes. Writes 32 bytes to `out_hash`.
//
// Feed the result to `ratify_session_context_build` as `request_hash` —
// binding the session but not the operation would let an intermediary
// attach a valid proof to the wrong action inside the right session.
enum RatifyStatus ratify_operation_context_hash(const char *required_scope,
                                                const char *operation,
                                                const char *resource_id,
                                                const char *requested_path,
                                                const unsigned char *payload_digest,
                                                uintptr_t payload_digest_len,
                                                unsigned char *out_hash,
                                                char **err_out);

// Build the 32-byte session_context over the SPEC §6.4.9 session
// context: the session a presentation belongs to plus (through
// `request_hash`) the operation it authorizes. Every string may be NULL
// (= empty); `request_hash` MUST be exactly 32 bytes — from
// `ratify_operation_context_hash`, over an all-NULL operation context
// when the deployment has no operation-specific inputs. Writes 32 bytes
// to `out_context`, ready for `RatifyVerifyOptions.session_context` and
// the challenge signing bytes. The Middleware Custody Profile (SPEC
// §15.2.1) requires all fields populated.
enum RatifyStatus ratify_session_context_build(const char *verifier_id,
                                               const char *workspace_id,
                                               const char *agent_id,
                                               const char *session_id,
                                               const char *invocation_id,
                                               const unsigned char *request_hash,
                                               uintptr_t request_hash_len,
                                               unsigned char *out_context,
                                               char **err_out);

// Compute the Protocol v2 operation request hash. `required_scope` must be a
// non-NULL registered canonical scope; other string fields may be NULL
// (empty). `payload_digest` is NULL (absent) or canonical
// `sha256:<64 lowercase hex>` text. Writes 32 bytes to `out_hash`.
// Missing output pointers return `RatifyErrNullPointer`; an invalid required
// scope or malformed digest returns `RatifyErrBadArgument`; invalid UTF-8
// returns `RatifyErrEncoding`.
enum RatifyStatus ratify_operation_context_v2_hash(const char *required_scope,
                                                   const char *operation,
                                                   const char *resource_id,
                                                   const char *requested_path,
                                                   const char *payload_digest,
                                                   unsigned char *out_hash,
                                                   char **err_out);

// Build the Protocol v2 session context from canonical verifier, workspace,
// and agent IDs plus session, invocation, and a 32-byte request hash. The
// verifier and agent IDs must be non-NULL 64-character lowercase hex strings;
// workspace_id must be a non-NULL lowercase UUID. NULL session_id and
// invocation_id mean empty. Missing required ID pointers return
// `RatifyErrNullPointer`; malformed IDs return `RatifyErrBadArgument`, and
// invalid UTF-8 returns `RatifyErrEncoding`.
enum RatifyStatus ratify_session_context_v2_build(const char *verifier_id,
                                                  const char *workspace_id,
                                                  const char *agent_id,
                                                  const char *session_id,
                                                  const char *invocation_id,
                                                  const unsigned char *request_hash,
                                                  uintptr_t request_hash_len,
                                                  unsigned char *out_context,
                                                  char **err_out);

// Create an in-memory challenge store holding at most `max_size` pending
// challenges. The store makes verifier-issued challenges single-use: each
// is accepted at most once within its freshness window; consuming a
// challenge removes its record, freeing the capacity slot immediately.
// Single-process only — deployments spanning processes or hosts need a
// store over shared storage with atomic consumption. Returns NULL when
// `max_size` is 0. Free with `ratify_challenge_store_free`.
struct RatifyChallengeStore *ratify_challenge_store_new(uintptr_t max_size);

// Free a `RatifyChallengeStore` handle. Safe to call with NULL.
void ratify_challenge_store_free(struct RatifyChallengeStore *store);

// Issue a fresh 32-byte challenge bound to `session_context` (which must
// be NULL/0 = unbound, or exactly 32 bytes), valid for `ttl_seconds`
// (which must be positive). Invalid inputs return RatifyErrBadArgument.
//
// - `out_challenge` — buffer of at least 32 bytes; receives the challenge.
// - `out_expires_at` — optional; receives the expiry (unix seconds).
enum RatifyStatus ratify_challenge_store_issue(const struct RatifyChallengeStore *store,
                                               const unsigned char *session_context,
                                               uintptr_t session_context_len,
                                               int64_t ttl_seconds,
                                               unsigned char *out_challenge,
                                               int64_t *out_expires_at,
                                               char **err_out);

// Report whether `challenge` could be consumed right now — issued,
// unexpired, unconsumed, and bound to `session_context` — WITHOUT
// consuming it. Returns RatifyOk when consumable; otherwise an error
// status with the documented unknown-challenge detail in `*err_out`.
// `now_unix` 0 = system clock.
enum RatifyStatus ratify_challenge_store_check(const struct RatifyChallengeStore *store,
                                               const unsigned char *challenge,
                                               uintptr_t challenge_len,
                                               const unsigned char *session_context,
                                               uintptr_t session_context_len,
                                               int64_t now_unix,
                                               char **err_out);

// Atomically remove the challenge's issuance record. Exactly one consume
// of a given challenge may ever succeed; later calls (and calls with a
// mismatched `session_context`, which do NOT remove the record) return an
// error status with the documented unknown-challenge detail in `*err_out`.
// Removal frees the record's capacity slot immediately.
// `now_unix` 0 = system clock.
enum RatifyStatus ratify_challenge_store_consume(const struct RatifyChallengeStore *store,
                                                 const unsigned char *challenge,
                                                 uintptr_t challenge_len,
                                                 const unsigned char *session_context,
                                                 uintptr_t session_context_len,
                                                 int64_t now_unix,
                                                 char **err_out);

// Verify a ProofBundle with single-use challenge enforcement (SPEC §10).
//
// Identical to `ratify_verify_bundle_opts`, plus: the store is consulted
// (without consuming) before any signature work, and the challenge is
// atomically consumed after the structural, chain, and challenge-signature
// checks pass — before authorization evaluation. A forged or malformed
// presentation never consumes a challenge; a cryptographically valid
// presentation does, even if authorization is subsequently denied.
//
// The store's session binding is checked against `opts->session_context`.
// `opts` may be NULL for default options.
enum RatifyStatus ratify_verify_bundle_opts_with_challenge_store(const char *bundle_json,
                                                                 const struct RatifyVerifyOptions *opts,
                                                                 const struct RatifyChallengeStore *store,
                                                                 struct RatifyVerifyResult **out,
                                                                 char **err_out);

// Compute the 16-byte hex identity from a hybrid public key (SPEC §7).
//
// `pub_json` is the public key JSON (`{"ed25519":"...","ml_dsa_65":"..."}`),
// as returned by `ratify_human_root_pub_key_json`. Free the result with
// `ratify_string_free`.
//
// A verifier that pins an identity by id uses this to confirm that a public
// key it has been given belongs to the principal it pinned (SPEC §15.4).
char *ratify_derive_id(const char *pub_json, char **err_out);

// Compute the full 256-bit Protocol v2 key ID from a hybrid public key.
// `pub_json` has the same JSON shape as `ratify_derive_id`. Free the result
// with `ratify_string_free`; invalid input returns null and sets `err_out`.
// The v1 symbol and its 128-bit output are unchanged.
char *ratify_derive_key_id_v2(const char *pub_json, char **err_out);

// Hash exactly 32 decoded Protocol v2 challenge bytes into a 48-byte replay
// digest. `out_digest` must point to 48 writable bytes. On failure it is
// zeroed when the declared capacity is at least 48 bytes. Null pointers
// return `RatifyErrNullPointer`; wrong lengths return `RatifyErrBadArgument`.
enum RatifyStatus ratify_challenge_claim_digest_v2(const unsigned char *challenge,
                                                   uintptr_t challenge_len,
                                                   unsigned char *out_digest,
                                                   uintptr_t out_digest_len,
                                                   char **err_out);

// Derive a 64-hex-character Protocol v2 claim ID from a UTF-8 namespace,
// epoch, and decoded challenge. Namespace is length-delimited and may contain
// NUL bytes. `out_id` needs at least 65 bytes including the terminator and
// starts with NUL on failure when writable. Null pointers return
// `RatifyErrNullPointer`, invalid UTF-8 returns `RatifyErrEncoding`, and
// empty namespaces, unsafe epochs, or wrong lengths return `RatifyErrBadArgument`.
enum RatifyStatus ratify_protocol_claim_id_v2(const unsigned char *namespace_,
                                              uintptr_t namespace_len,
                                              uint64_t replay_epoch,
                                              const unsigned char *challenge,
                                              uintptr_t challenge_len,
                                              char *out_id,
                                              uintptr_t out_id_len,
                                              char **err_out);

// Derive the same ID from a precomputed 48-byte v2 challenge claim digest.
// `out_id` needs 65 bytes; failure clears its first byte when writable.
enum RatifyStatus ratify_protocol_claim_id_from_digest_v2(const unsigned char *namespace_,
                                                          uintptr_t namespace_len,
                                                          uint64_t replay_epoch,
                                                          const unsigned char *digest,
                                                          uintptr_t digest_len,
                                                          char *out_id,
                                                          uintptr_t out_id_len,
                                                          char **err_out);

// Verify both Protocol v2 delegation signature components over the caller's
// exact caller-provided signable bytes. This primitive does not check that
// those bytes are a canonical certificate projection, check its key ID, or
// authorize a delegation. `signable` must be non-null and readable for
// `signable_len` bytes. Writes 1 or 0 to `valid_out`, including 0 on error.
enum RatifyStatus ratify_verify_delegation_signature_v2(const unsigned char *signable,
                                                        uintptr_t signable_len,
                                                        const char *signature_json,
                                                        const char *public_key_json,
                                                        int *valid_out,
                                                        char **err_out);

// Return the canonical delegation-cert signing bytes as a lowercase hex string.
char *ratify_delegation_sign_bytes_hex(const char *cert_json, char **err_out);

// Return the challenge signing bytes as a lowercase hex string.
//
// One entry point covers all three challenge-bytes variants in
// `docs/SDKS.md` §4, which explicitly permits optional arguments where that is
// idiomatic:
//
// - plain (`challenge || BE u64(ts)`): pass NULL for both optional pointers;
// - session-bound (SPEC §5.8): pass a 32-byte `session_context`;
// - stream-bound: additionally pass a 32-byte `stream_id` and `stream_seq`.
//
// `challenge` must point to exactly `challenge_len` bytes. `session_context`
// and `stream_id`, when non-NULL, MUST each be exactly 32 bytes.
char *ratify_challenge_sign_bytes_hex(const unsigned char *challenge,
                                      uintptr_t challenge_len,
                                      int64_t challenge_at_unix,
                                      const unsigned char *session_context,
                                      uintptr_t session_context_len,
                                      const unsigned char *stream_id,
                                      uintptr_t stream_id_len,
                                      int64_t stream_seq,
                                      char **err_out);

// Canonicalise a JSON document (SPEC §6). Returns the canonical form as a
// string; free with `ratify_string_free`. Provided for interop audit, which is
// what §4 names it for.
char *ratify_canonical_json(const char *json, char **err_out);

// Rebuild a HumanRoot deterministically from two 32-byte seeds.
//
// This is the supported way to persist an issuer identity in C: store the two
// seeds as key material and reconstruct the identity after a restart. The
// protocol deliberately specifies no private-key serialisation format, so
// seeds are the portable unit.
//
// `created_at_unix` is carried into the rebuilt identity so that a restored
// root is byte-identical to the original rather than merely equivalent.
//
// Both seeds MUST be 32 bytes and MUST come from a cryptographically secure
// source. Anyone holding them holds the identity.
enum RatifyStatus ratify_human_root_from_seeds(const unsigned char *ed_seed,
                                               uintptr_t ed_seed_len,
                                               const unsigned char *ml_seed,
                                               uintptr_t ml_seed_len,
                                               int64_t created_at_unix,
                                               struct RatifyHumanRoot **out,
                                               char **err_out);

// Rebuild an AgentIdentity deterministically from two 32-byte seeds.
// See `ratify_human_root_from_seeds` for the seed-custody warning.
enum RatifyStatus ratify_agent_from_seeds(const char *name_utf8,
                                          const char *agent_type_utf8,
                                          const unsigned char *ed_seed,
                                          uintptr_t ed_seed_len,
                                          const unsigned char *ml_seed,
                                          uintptr_t ml_seed_len,
                                          int64_t created_at_unix,
                                          struct RatifyAgent **out,
                                          char **err_out);

// Verify a delegation cert's own hybrid signature. Writes 1 or 0 to
// `valid_out`. This checks only the signature on this one cert; full chain
// verification is `ratify_verify_bundle`.
enum RatifyStatus ratify_verify_delegation_signature(const char *cert_json,
                                                     int *valid_out,
                                                     char **err_out);

// Sign a challenge with an agent's private key, returning the hybrid
// signature as JSON. Free with `ratify_string_free`.
//
// Optional bindings match `ratify_challenge_sign_bytes_hex`: pass NULL for
// both to sign the plain preimage, a 32-byte `session_context` for the
// session-bound form, and additionally a 32-byte `stream_id` plus
// `stream_seq` for the stream-bound form.
char *ratify_agent_sign_challenge(const struct RatifyAgent *agent,
                                  const unsigned char *challenge,
                                  uintptr_t challenge_len,
                                  int64_t challenge_at_unix,
                                  const unsigned char *session_context,
                                  uintptr_t session_context_len,
                                  const unsigned char *stream_id,
                                  uintptr_t stream_id_len,
                                  int64_t stream_seq,
                                  char **err_out);

// Verify a hybrid challenge signature against a public key. Writes 1 or 0 to
// `valid_out`. Optional bindings match `ratify_agent_sign_challenge`; they
// MUST match what was signed or verification fails.
enum RatifyStatus ratify_verify_challenge_signature(const unsigned char *challenge,
                                                    uintptr_t challenge_len,
                                                    int64_t challenge_at_unix,
                                                    const unsigned char *session_context,
                                                    uintptr_t session_context_len,
                                                    const unsigned char *stream_id,
                                                    uintptr_t stream_id_len,
                                                    int64_t stream_seq,
                                                    const char *sig_json,
                                                    const char *pub_json,
                                                    int *valid_out,
                                                    char **err_out);

// Generate a random hybrid keypair from the OS RNG.
//
// The public half is returned as JSON. The private half is returned as the
// two 32-byte seeds that reproduce it through `ratify_human_root_from_seeds`
// or `ratify_agent_from_seeds`: the protocol specifies no private-key
// serialisation format, so seeds are this SDK's portable unit of private key
// material. Both output buffers MUST be at least 32 bytes. Treat them as key
// material.
enum RatifyStatus ratify_generate_hybrid_keypair(char **out_pub_json,
                                                 unsigned char *out_ed_seed,
                                                 unsigned char *out_ml_seed,
                                                 char **err_out);

// Return the operation-context preimage (SPEC §6.4.9) as a lowercase hex
// string. `ratify_operation_context_hash` returns the digest over these bytes;
// audit tooling needs the bytes themselves. Parameters match that function.
char *ratify_operation_context_bytes_hex(const char *required_scope,
                                         const char *operation,
                                         const char *resource_id,
                                         const char *requested_path,
                                         const unsigned char *payload_digest,
                                         uintptr_t payload_digest_len,
                                         char **err_out);

// Return the session-context preimage (SPEC §6.4.9) as a lowercase hex
// string. Parameters match `ratify_session_context_build`, which returns the
// digest over these bytes.
char *ratify_session_context_bytes_hex(const char *verifier_id,
                                       const char *workspace_id,
                                       const char *agent_id,
                                       const char *session_id,
                                       const char *invocation_id,
                                       const unsigned char *request_hash,
                                       uintptr_t request_hash_len,
                                       char **err_out);

// Serialise an agent's hybrid public key to JSON, for feeding to
// `ratify_verify_challenge_signature` and `ratify_derive_id`. The symmetric
// accessor for human roots already existed; without this one an agent's key
// could not be handed to the verification primitives at all. Free with
// `ratify_string_free`.
char *ratify_agent_pub_key_json(const struct RatifyAgent *agent, char **err_out);

// Returns `RATIFY_V2_ABI_VERSION` as compiled into this library. A caller
// built against a header with a different value must not use `ratify_v2_*`.
uint32_t ratify_v2_abi_version(void);

// Returns the Protocol major version implemented by `ratify_v2_*` (2).
uint32_t ratify_v2_protocol_version(void);

// Returns the library package version (e.g. "2.0.0-alpha.1"). Statically
// allocated — do NOT free. Same value as `ratify_version()`.
const char *ratify_v2_library_version(void);

// Returns the IANA time zone database release pinned for `time_window`
// evaluation (e.g. "2025c"; SPEC-v2 §5.2, Go `TZDBVersionV2`). A verifier
// configuration's `tzdb_version` must equal it. Statically allocated; do
// NOT free.
const char *ratify_v2_tzdb_version(void);

// Returns the stable spelling for a `ratify_v2_*` result code: "ok", a
// SPEC-v2 §2.7 failure class (e.g. "invalid_signature"), an ABI condition
// ("null_pointer", "bad_argument", "internal", "cancelled"), a store
// sentinel, a signing refusal, or "unknown". Statically allocated — do NOT
// free.
const char *ratify_v2_error_class_str(int32_t code);

// The diagnostic message of the most recent `ratify_v2_*` call on the
// calling thread ("" after a success). The pointer is owned by the library
// and valid until the next `ratify_v2_*` call on this thread — do NOT free.
const char *ratify_v2_last_error_message(void);

// Release a buffer returned by the library. Safe to call with an empty
// buffer. Each buffer must be freed exactly once.
void ratify_v2_buffer_free(struct RatifyV2Buffer buffer);

// Release a string returned by a `ratify_v2_*` function. NULL is a no-op.
void ratify_v2_string_free(char *s);

// 1 when the evaluator call's deadline has passed (return now), else 0.
int32_t ratify_v2_evaluator_call_expired(const struct RatifyV2EvaluatorCall *call);

// Strictly decode `wire` as `kind` (a `RatifyV2ObjectKind`), applying the
// object's byte limit before parsing: a `wire_len` over the limit, up to
// `SIZE_MAX`, is `malformed` and `wire` is not read. When `canonical_out`
// is non-NULL the canonical re-encoding is written there (it equals `wire`
// for every conforming object). Signed objects 1..=8 are decoded with all
// their structural checks; a transaction receipt also verifies its
// signatures.
// A status evidence batch (101) is decoded at the envelope only (SPEC-v2
// §6.5 step 3): the strict JSON value model applies to the whole document,
// but its nested objects are not decoded. A non-NULL `canonical_out` asks
// for the §6.5 canonical batch encoding, which writes each object's
// canonical encoding, so the call then also decodes every nested object
// under its code and is `malformed` when one does not decode, as the other
// SDKs' batch encoders are.
int32_t ratify_v2_object_decode(int32_t kind,
                                const uint8_t *wire,
                                uintptr_t wire_len,
                                struct RatifyV2Buffer *canonical_out);

// The exact signable projection (SPEC-v2 §5) of `wire` under signature code
// `object_type_code` (0x0001..=0x0009): the certificate body, the challenge
// presentation of a proof bundle, the status object body, the rotation
// statement body (both 0x0004 and 0x0009), the witness entry, the shared
// transaction statement, or the receipt body. The object is strictly
// decoded first.
int32_t ratify_v2_signable_bytes(uint32_t object_type_code,
                                 const uint8_t *wire,
                                 uintptr_t wire_len,
                                 struct RatifyV2Buffer *out);

// The 77-byte signing transcript `M` (SPEC-v2 §3.1) for `signable` under
// `object_type_code`.
int32_t ratify_v2_signing_message(uint32_t object_type_code,
                                  const uint8_t *signable,
                                  uintptr_t signable_len,
                                  struct RatifyV2Buffer *out);

// The 22-byte FIPS 204 ML-DSA-65 context of `object_type_code`
// (`ratify-protocol/2/` + lowercase 4-hex code).
int32_t ratify_v2_mldsa_context(uint32_t object_type_code, struct RatifyV2Buffer *out);

// The 64-byte external μ an external-μ provider signs (SPEC-v2 §3.1):
// `SHAKE256(SHAKE256(pk, 64) || 0x00 || len(ctx) || ctx || M, 64)` for the
// registry context of `object_type_code` and the 77-byte transcript
// `message`. Provided for adapter checks and conformance; signing computes
// μ itself.
int32_t ratify_v2_external_mu(const struct RatifyV2PublicKey *key,
                              uint32_t object_type_code,
                              const uint8_t *message,
                              uintptr_t message_len,
                              struct RatifyV2Buffer *out);

// Verify both components of a hybrid signature over `signable` under
// `object_type_code` and a complete public key with the ordinary verifier.
// A code outside the registry is `unsupported_object_type`; a failing
// component is `invalid_signature`.
int32_t ratify_v2_verify_statement(uint32_t object_type_code,
                                   const uint8_t *signable,
                                   uintptr_t signable_len,
                                   struct RatifyV2Slice signature_ed25519,
                                   struct RatifyV2Slice signature_ml_dsa_65,
                                   const struct RatifyV2PublicKey *key);

// `delegation_digest` (48 bytes) recomputed over the delegations of a
// strictly decoded proof bundle.
int32_t ratify_v2_delegation_digest(const uint8_t *bundle,
                                    uintptr_t bundle_len,
                                    struct RatifyV2Buffer *out);

// `BundleHashV2` (`"sha384:" + 96 hex`) of a strictly decoded proof bundle.
// Free `*out` with `ratify_v2_string_free`.
int32_t ratify_v2_bundle_hash(const uint8_t *bundle, uintptr_t bundle_len, char **out);

// `ChallengeClaimDigest` (48 bytes) of exactly 32 challenge bytes.
int32_t ratify_v2_challenge_claim_digest(const uint8_t *challenge,
                                         uintptr_t challenge_len,
                                         struct RatifyV2Buffer *out);

// The stable claim ID (64 lowercase hex) for a UTF-8 verifier namespace
// (length-delimited; may contain NUL), replay epoch (0..2^53-1), and 32
// challenge bytes. Free `*out` with `ratify_v2_string_free`.
int32_t ratify_v2_claim_id(const uint8_t *namespace_ptr,
                           uintptr_t namespace_len,
                           int64_t replay_epoch,
                           const uint8_t *challenge,
                           uintptr_t challenge_len,
                           char **out);

// The claim ID from a precomputed 48-byte `ChallengeClaimDigest`.
int32_t ratify_v2_claim_id_from_digest(const uint8_t *namespace_ptr,
                                       uintptr_t namespace_len,
                                       int64_t replay_epoch,
                                       const uint8_t *claim_digest,
                                       uintptr_t claim_digest_len,
                                       char **out);

// `StatusEvidenceDigest` (48 bytes) of a strictly decoded revocation list
// (`kind` 3) or revocation push (`kind` 5), over the complete signed object.
int32_t ratify_v2_status_evidence_digest(int32_t kind,
                                         const uint8_t *wire,
                                         uintptr_t wire_len,
                                         struct RatifyV2Buffer *out);

// `StatementBodyDigest(code, body)` (48 bytes) over an exact canonical
// signable body, defined for codes 0x0003, 0x0004, 0x0005, 0x0006 and
// 0x0008; any other code is `unsupported_object_type`.
int32_t ratify_v2_statement_body_digest(uint32_t object_type_code,
                                        const uint8_t *body,
                                        uintptr_t body_len,
                                        struct RatifyV2Buffer *out);

// `StatementBodyDigest` (48 bytes) of a strictly decoded signed object:
// the chain digest of a rotation statement (`kind` 4), witness entry (6),
// or verification receipt (8), and the digest of the signable projection
// of a revocation list (3) or push (5). Kinds 1, 2 and 7 are
// `unsupported_object_type` (SPEC-v2 §4). It is independent of signature
// bytes, so hedged re-signatures share it.
int32_t ratify_v2_object_body_digest(int32_t kind,
                                     const uint8_t *wire,
                                     uintptr_t wire_len,
                                     struct RatifyV2Buffer *out);

// `RevokedSetDigest` (48 bytes) of a JSON array of revoked `cert_id`
// strings: deduplicated, sorted by UTF-8 bytes, canonical JSON, SHA-384
// under the `ratify-protocol-revoked-set-v2` tag.
int32_t ratify_v2_revoked_set_digest(const uint8_t *cert_ids_json,
                                     uintptr_t cert_ids_json_len,
                                     struct RatifyV2Buffer *out);

// `ReceiptOutboxDigest` (`"sha384:" + 96 hex`) of an exact sealed outbox
// body. Free `*out` with `ratify_v2_string_free`.
int32_t ratify_v2_receipt_outbox_digest(const uint8_t *body, uintptr_t body_len, char **out);

// `SecurityJournalDigest` (`"sha384:" + 96 hex`) of a canonical
// `SecurityJournalV2` snapshot. Free `*out` with `ratify_v2_string_free`.
int32_t ratify_v2_security_journal_digest(const uint8_t *snapshot,
                                          uintptr_t snapshot_len,
                                          char **out);

// The sealed receipt outbox body (SPEC-v2 §7.7) of a strictly decoded
// signed verification receipt.
int32_t ratify_v2_verification_receipt_body(const uint8_t *receipt,
                                            uintptr_t receipt_len,
                                            struct RatifyV2Buffer *out);

// The 32-byte transaction context (SPEC-v2 §2.4) of a transaction ID, terms
// schema URI, and exact canonical terms JSON. It needs no parties or
// signatures, so it can be computed before any party signs.
int32_t ratify_v2_transaction_context_hash(const char *transaction_id,
                                           const char *terms_schema_uri,
                                           const uint8_t *terms_canonical_json,
                                           uintptr_t terms_canonical_json_len,
                                           struct RatifyV2Buffer *out);

// The 32-byte per-party request hash (SPEC-v2 §2.4) of a transaction
// context and the party's required scope.
int32_t ratify_v2_transaction_party_request_hash(const uint8_t *transaction_context,
                                                 uintptr_t transaction_context_len,
                                                 const char *required_scope,
                                                 struct RatifyV2Buffer *out);

// The 32-byte operation `request_hash` (SPEC-v2 §2.4) of
// `{"required_scope", "operation", "resource_id", "requested_path",
// "payload_digest_b64"}` (payload digest empty or exactly 32 bytes).
int32_t ratify_v2_operation_context_hash(const uint8_t *operation_json,
                                         uintptr_t operation_json_len,
                                         struct RatifyV2Buffer *out);

// The 32-byte `session_context` (SPEC-v2 §2.4) of `{"verifier_id",
// "workspace_id", "agent_id", "session_id", "invocation_id",
// "request_hash_b64"}`.
int32_t ratify_v2_session_context(const uint8_t *inputs_json,
                                  uintptr_t inputs_json_len,
                                  struct RatifyV2Buffer *out);

// Decode the managed Verify API text form of a payload digest (§7.12).
// NULL `encoded` means absent. `*present` is 1 when a 32-byte digest was
// decoded into `out`, 0 when the input encodes "no digest".
int32_t ratify_v2_payload_digest_decode(const char *encoded,
                                        struct RatifyV2Buffer *out,
                                        int32_t *present);

// The context policy digest of `{"profile", "require_bound",
// "required_fields", "expected_session_context_b64"}` (the expected session
// context is excluded from the digest). Free `*out` with
// `ratify_v2_string_free`.
int32_t ratify_v2_context_policy_digest(const uint8_t *policy_json,
                                        uintptr_t policy_json_len,
                                        char **out);

// The extension evaluator profile digest (`"sha384:" + 96 hex`) of a
// `{profile, type}` descriptor. Free `*out` with `ratify_v2_string_free`.
int32_t ratify_v2_constraint_profile_digest(const char *profile,
                                            const char *constraint_type,
                                            char **out);

// RatifyCanonicalJSON (Annex A) of a strictly decoded JSON value.
int32_t ratify_v2_canonical_json(const uint8_t *data,
                                 uintptr_t data_len,
                                 struct RatifyV2Buffer *out);

// Validate a JSON array of delegation scopes under the v2 scope rules.
int32_t ratify_v2_validate_scopes(const uint8_t *scopes_json, uintptr_t scopes_json_len);

// Validate one request `required_scope` (SPEC-v2 §2.4):
// `invalid_required_scope` unless it is one canonical non-wildcard scope or
// one exact `custom:` scope.
int32_t ratify_v2_validate_required_scope(const char *scope);

// Validate a request context JSON (the `"context"` member schema of the
// verification request) against the extension-context bounds
// (`configuration_invalid` when out of bounds).
int32_t ratify_v2_validate_request_context(const uint8_t *context_json, uintptr_t context_json_len);

// Run one of the two built-in standard evaluator profiles
// (`com.ratifyprotocol.max_count/v1`, `com.ratifyprotocol.allowed_values/v1`)
// on an input `{"type", "params": <any JSON>, "delegation_index",
// "constraint_index", "issuer_id", "cert_id", "context": <request context>,
// "evaluation_time"}`; an absent `params` member means no params object.
// Writes the outcome (`RatifyV2EvaluatorOutcome`), the pass horizon (0 =
// none), and the diagnostic detail (free with `ratify_v2_string_free`;
// `detail_out` may be NULL).
int32_t ratify_v2_evaluate_standard_profile(const char *profile,
                                            const uint8_t *input_json,
                                            uintptr_t input_json_len,
                                            int32_t *outcome_out,
                                            int64_t *valid_until_out,
                                            char **detail_out);

// Whether an authoritative time `now` is inside a claim's sealed challenge
// bounds with exclusive deadlines (`issued_at <= now + skew`, `now <
// expires_at`, `now < issued_at + max_age`). Returns 1 or 0; 0 on any
// failure, including a timestamp outside 0..=253402300799, `max_age_seconds`
// outside 1..=300 or `clock_skew_seconds` outside 0..=300 (the SPEC-v2 §2.5
// bounds every sealed claim satisfies). For claim stores implementing the
// freshness recheck.
int32_t ratify_v2_challenge_time_current(int64_t issued_at,
                                         int64_t expires_at,
                                         int64_t max_age_seconds,
                                         int64_t clock_skew_seconds,
                                         int64_t now);

// The stream-sequence rule of SPEC-v2 §7.4 for a claim store: `has_last`
// says whether the stream has an accepted sequence `last`; `seq` is the
// presented sequence. Returns 0 to accept or `stream_sequence_mismatch` /
// `malformed`.
int32_t ratify_v2_check_stream_sequence(int32_t has_last, int64_t last, int64_t seq);

// The finalization binding of SPEC-v2 §7.5 for a claim store's `finalize`
// (Go `ValidateV2FinalizationPayload`). `claim_record` is the claim's
// `RatifyV2ClaimView.record` as the store persisted it. Returns 0 when the
// receipt body decodes strictly as a canonical receipt outbox body whose
// `verifier_id`, `agent_id`, `bundle_hash`, `issuer_ids` (the sorted,
// distinct sealed issuer IDs), `required_scope` and `constraint_evaluators`
// equal the sealed claim's, whose `context_policy_digest` equals the sealed
// claim's (null for a policy-less claim) unless `context_assessment` is
// `not_evaluated`, when it is null, and the terminal result is exactly the
// RatifyCanonicalJSON of the body's `decision`, `decision_reason` and
// `identity_status` (SPEC-v2 §7.13). Otherwise
// `malformed` (the body does not decode) or `configuration_invalid` (any
// difference); a store commits nothing in either case. A `claim_record` that is not a claim record is
// `bad_argument`.
int32_t ratify_v2_validate_finalization_payload(const uint8_t *claim_record,
                                                uintptr_t claim_record_len,
                                                const uint8_t *terminal_result,
                                                uintptr_t terminal_result_len,
                                                const uint8_t *receipt_body,
                                                uintptr_t receipt_body_len);

// Whether `outcome` (a `RatifyV2ReleaseStatus`) and `reason` form a release
// record (SPEC-v2 §6.9; Go `ValidV2ReleaseRecordOutcome`): released with
// the reason "", or withheld with "clock_regressed", "challenge_expired" or
// "allow_horizon_passed". Returns 1 or 0; a NULL or non-UTF-8 `reason` is 0
// (SPEC-v2 §1.3: a predicate fails closed). For claim stores implementing
// `record_release`.
int32_t ratify_v2_valid_release_record_outcome(int32_t outcome, const char *reason);

// Whether `progress` is a valid evaluation progress record (SPEC-v2 §7.5;
// Go `ValidateV2EvaluationProgress`): the RatifyCanonicalJSON object the
// `record_progress` callback receives, with exactly the members
// `context_assessment`, `context_policy_digest` (a digest or null),
// `status_assessment`, `status_evidence_digests` and `trust_assessment`
// and valid values. Returns 1 or 0; NULL with a nonzero length, invalid
// JSON, a non-canonical encoding and an invalid record are 0 (SPEC-v2
// §1.3: a predicate fails closed). A
// claim store implementing `record_progress` rejects a record for which
// this is 0 as `RatifyV2Malformed` and stores nothing.
int32_t ratify_v2_valid_evaluation_progress(const uint8_t *progress, uintptr_t progress_len);

// Whether `claim` is keyed by its replay key (SPEC-v2 §2.4, §7.3): its
// `record` is a claim record whose `claim_id`, `namespace` and
// `replay_epoch` equal the view's, and `claim_id` is the stable claim ID
// derived from that namespace, epoch and the record's `sha384:` challenge
// digest. Every other scalar field of the view (agent, issuance, expiry,
// maximum age, clock skew, stream and rate batch) must also equal the
// record's, so a store's freshness, stream and rate rules read the sealed
// claim. Returns 1 or 0; NULL and any undecodable view are 0 (SPEC-v2
// §1.3). A claim store keyed by claim ID refuses a claim for which this is
// 0 as `RatifyV2ConfigurationInvalid` and creates nothing, so a supplied ID
// cannot open a second claim for one challenge.
int32_t ratify_v2_claim_id_matches_key(const struct RatifyV2ClaimView *claim);

// Verify one cross-SDK fixture file (`testvectors/v2/cross-sdk/<sdk>.json`)
// with the README procedure: strict decode, `sdk == expected_sdk`, key
// derivation from seeds, byte-identical re-encoding, every signature
// transcript and signature, and the required kinds and coverage.
int32_t ratify_v2_cross_sdk_fixture_verify(const uint8_t *fixture,
                                           uintptr_t fixture_len,
                                           const char *expected_sdk);

// Derive a key pair from a 32-byte Ed25519 seed and a 32-byte ML-DSA-65
// seed (FIPS 204 `KeyGen_internal(ξ)`), the derivation every SDK and the
// `keys.json` fixtures use. Seeds are copied; the caller may wipe them after
// the call. On success `*out` is a new handle.
int32_t ratify_v2_keypair_from_seeds(const uint8_t *ed25519_seed,
                                     const uint8_t *ml_dsa_65_seed,
                                     struct RatifyV2KeyPair **out);

// Generate a fresh key pair from the operating-system random source (or the
// custom entropy source of a `custom-entropy` build). When
// `ed25519_seed_out` / `ml_dsa_65_seed_out` are non-NULL, the 32-byte seeds
// are written there so the caller can persist or export the key; pass NULL to
// keep them inside the library.
int32_t ratify_v2_keypair_generate(struct RatifyV2KeyPair **out,
                                   uint8_t *ed25519_seed_out,
                                   uint8_t *ml_dsa_65_seed_out);

// Release a key pair. NULL is a no-op. The private key is wiped and dropped
// from library memory.
void ratify_v2_keypair_free(struct RatifyV2KeyPair *kp);

// Write the complete public key of `kp` into `*out`.
int32_t ratify_v2_keypair_public_key(const struct RatifyV2KeyPair *kp,
                                     struct RatifyV2PublicKey *out);

// Write the 64-character `key_id_v2` of `kp` plus NUL into `out`
// (`out_len` >= `RATIFY_V2_KEY_ID_BUF_LEN`).
int32_t ratify_v2_keypair_key_id(const struct RatifyV2KeyPair *kp, char *out, uintptr_t out_len);

// Compute `key_id_v2` of a complete public key (SPEC-v2 §2.3) into `out`
// (`out_len` >= 65).
int32_t ratify_v2_public_key_id(const struct RatifyV2PublicKey *key, char *out, uintptr_t out_len);

// Encode a public key as the wire JSON object
// `{"ed25519":"<b64>","ml_dsa_65":"<b64>"}` (for request and context JSON).
// Free `*out` with `ratify_v2_string_free`.
int32_t ratify_v2_public_key_to_json(const struct RatifyV2PublicKey *key, char **out);

// Derive the full 256-bit v2 key ID
// (`hex(SHA-256("ratify-key-id-v2\0" || ed25519 || ml_dsa_65))`) and write it
// as 64 lowercase hex characters plus NUL into `out` (`out_len` >= 65,
// `RATIFY_V2_KEY_ID_BUF_LEN`). Wrong key lengths return `RatifyV2Malformed`.
int32_t ratify_v2_key_id(const uint8_t *ed25519,
                         uintptr_t ed25519_len,
                         const uint8_t *ml_dsa_65,
                         uintptr_t ml_dsa_65_len,
                         char *out,
                         uintptr_t out_len,
                         char **err_out);

// Check that `key_id` is a well-formed v2 key ID (64 lowercase hex chars).
// A 128-bit v1 ID, uppercase hex, or wrong length returns `RatifyV2Malformed`.
int32_t ratify_v2_key_id_check(const char *key_id, char **err_out);

// Strictly decode a canonical v2 signed object of `kind`
// (`RatifyV2ObjectKind`) from `wire` and verify it per the SPEC-v2 procedure
// for that kind. Returns `RatifyV2Ok` or the failure class.
//
// `verify_context_json` is required for kinds that verify against
// caller-authenticated state and may be NULL otherwise:
//
// - revocation_list / revocation_push:
//   `{"bound_issuer_id": "<v2 id>", "status_key": <HybridPublicKey>}`
// - key_rotation_statement:
//   `{"rotation_state": {"authority_id", "recovery_epoch", "role", "sequence",
//   "head_hash_b64", "current_key": <HybridPublicKey>, "used_key_ids": [..]},
//   "now": <unix>, "future_skew_seconds": <int>}`
// - witness_entry: `{"witness_key": <HybridPublicKey>, "head": <head>}`
// - verification_receipt: `{"verifier_key": <HybridPublicKey>, "head": <head>}`
//
// Each context has exactly the members listed for its kind; an unknown
// member is `RatifyV2ErrBadArgument`.
//
// `<head>` is `{"log_id", "sequence", "head_hash_b64",
// "accepted_digests_b64": {"<seq>": "<b64>"}, "frozen"}` plus `"verifier_id"`
// for a verification receipt. `<HybridPublicKey>` is
// `{"ed25519": "<b64>", "ml_dsa_65": "<b64>"}`.
int32_t ratify_v2_verify_object(int32_t kind,
                                const uint8_t *wire,
                                uintptr_t wire_len,
                                const char *verify_context_json,
                                char **err_out);

// Strictly decode a v2 ProofBundle and run its structural checks (key IDs,
// delegation digest, duplicate CertificateRef, chain linkage) and every
// certificate and challenge signature. This is NOT a full live verification:
// it performs no trust-anchor, challenge, replay, status, or policy checks.
//
// When `bundle_hash_out` is non-NULL, the BundleHashV2 of a verified bundle is
// written there as a NUL-terminated string (`bundle_hash_out_len` bytes
// available; 128 is sufficient).
int32_t ratify_v2_proof_bundle_verify_signatures(const uint8_t *wire,
                                                 uintptr_t wire_len,
                                                 char *bundle_hash_out,
                                                 uintptr_t bundle_hash_out_len,
                                                 char **err_out);

// Verify a v2 VerificationReceipt against a caller-authenticated verifier key
// and log head. `head_json` uses the `<head>` shape documented on
// `ratify_v2_verify_object` (including `verifier_id`).
int32_t ratify_v2_verification_receipt_verify(const uint8_t *wire,
                                              uintptr_t wire_len,
                                              const uint8_t *verifier_ed25519,
                                              uintptr_t verifier_ed25519_len,
                                              const uint8_t *verifier_ml_dsa_65,
                                              uintptr_t verifier_ml_dsa_65_len,
                                              const char *head_json,
                                              char **err_out);

// Check that a v2 VerificationReceipt is bound to a v2 ProofBundle (bundle
// hash, verifier ID, agent ID, issuer IDs). Mismatch returns
// `RatifyV2ReceiptBundleMismatch`.
int32_t ratify_v2_receipt_bundle_binding_check(const uint8_t *receipt_wire,
                                               uintptr_t receipt_wire_len,
                                               const uint8_t *bundle_wire,
                                               uintptr_t bundle_wire_len,
                                               char **err_out);

